<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization__main">
      <div class="optimization__main-manu">
        <div class="optimization__manu-item">
          <ButtonUI
            svg="back-arrow-svg"
            buttonClass="btn--second"
            @action="rejectPublication"
          />
          <p class="optimization__manu-title" v-if="id !== 'new'">
            Редактирование Записей #{{ id }}
          </p>
          <p class="optimization__manu-title" v-else>Новая запись</p>
        </div>
        <div class="optimization__manu-item">
          <ButtonUI
            svg="info-svg"
            buttonClass="btn--second"
            @action="openMenu('Reference')"
          />
          <ButtonUI
            v-if="id !== 'new'"
            svg="templates-svg"
            text="Применить шаблон"
            buttonClass="btn--primary"
            @action="openMenu('Templates')"
          />
        </div>
      </div>
      <div class="optimization-option">
        <ul class="optimization-option__form">
          <li class="optimization-option__item">
            <span class="optimization-option__text">Раздел</span>
            <CustomSelect
              v-model="selectPartition"
              placeholder="Автомобили"
              :options="selectPartitions"
            />
          </li>
          <li class="optimization-option__item" v-if="selectPartition?.code">
            <span class="optimization-option__text">URL</span>
            <CustomInput v-model="inputUrl" placeholder="URL" />
          </li>
          <li class="optimization-option__item" v-if="id !== 'new'">
            <span class="optimization-option__text">Созданно</span>
            <p>{{ createItem }}</p>
          </li>
          <li class="optimization-option__item" v-if="id !== 'new'">
            <span class="optimization-option__text">Изменено</span>
            <div class="optimization-option__item-btn">
              <span>{{ updateItem }}</span>
              <ButtonUI
                svg="history-svg"
                text="история изменений"
                v-if="historyChange"
                @action="openMenu('Log')"
                buttonClass="btn--second"
              />
            </div>
          </li>
        </ul>
      </div>
      <ul class="optimization-option__list-box" v-if="selectPartition.code">
        <li class="optimization-option__item">
          <span class="optimization-option__text">Noindex</span>
          <CheckboxUI label="Да" v-model="noIndex.value" />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">Город</span>
          <CustomSelectSearch
            v-if="!inputCity.value"
            v-model="selectedLocation"
            :options="locationOptions"
          />
          <CustomInput
            v-else
            v-model="inputCity.value"
            :text="inputCity.error ? inputCity.errorText : inputCity.text"
            :placeholder="inputCity.placeholder"
            :error="inputCity.error"
          />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">H1</span>
          <CustomInput
            v-model="inputH1.value"
            placeholder="h1"
            :error="inputH1.error"
          />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">Title</span>
          <CustomInput
            v-model="inputTitle.value"
            placeholder="h1"
            :error="inputTitle.error"
          />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">Description</span>
          <CutomTextArea
            v-model="inputDescr.value"
            placeholder="Description"
            :error="inputDescr.error"
          />
        </li>

        <li class="optimization-option__item">
          <span class="optimization-option__text">keywords</span>
          <CutomTextArea
            v-model="inputKeywords.value"
            placeholder="keywords"
            :error="inputKeywords.error"
          />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">SEO text</span>
          <CutomTextArea
            v-model="inputSeoText.value"
            placeholder="SEO Text"
            :error="inputSeoText.error"
          />
        </li>

        <li class="optimization-option__item">
          <span class="optimization-option__text">Header</span>
          <CutomTextArea
            v-model="inputHeader.value"
            placeholder="Header"
            :error="inputHeader.error"
          />
        </li>

        <li class="optimization-option__item">
          <span class="optimization-option__text">Footer</span>
          <CutomTextArea
            v-model="inputFooter.value"
            placeholder="Footer"
            :error="inputFooter.error"
          />
        </li>
      </ul>

      <CustomMenu
        v-if="isMenuOpen"
        :name="menuName"
        :data="historyChange.data"
        @closing="isMenuOpen = false"
        @submit-action="chouseItem"
      />

      <div class="optimization-option__btn-box" v-if="isFormChanged">
        <ButtonUI
          :loading="isloading"
          text="Сохранить"
          buttonClass="btn--primary"
          @action="saveForm"
        />
        <ButtonUI
          :loading="isloading"
          text="Сохранить как шаблон"
          buttonClass="btn--second"
          @action="openMenu('Templates')"
        />
        <ButtonUI
          :loading="isloading"
          text="Отменить"
          buttonClass="btn--second"
          @action="resetFilterValue"
        />
      </div>
    </div>
    <template v-if="showExitConfirm">
      <div class="modal-overlay">
        <div class="modal-window">
          <p class="modal-title">
            Вы уверены, что хотите покинуть страницу? Несохраненные данные будут
            потеряны.
          </p>
          <div class="modal-actions">
            <ButtonUI
              :buttonClass="`btn--second`"
              text="Всё равно покинуть"
              @click="confirmExit"
            />
            <ButtonUI text="Продолжить" @click="cancelExit" />
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';

import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import ButtonUI from '@/components/UI/ButtonUI';
import CustomInput from '@/components/UI/CustomInput';
import CheckboxUI from '@/components/UI/CheckboxUI';
import CutomTextArea from '@/components/UI/CutomTextArea';
import CustomSelectSearch from '@/components/UI/CustomSelectSearch';

import CustomMenu from '@/components/Menu/CustomMenu.vue';

import CustomSelect from '@/components/UI/CustomSelect';

import { FORMATER } from '@/composables/formater.js';
import { useValidate } from '@/composables/useValidate.js';

import { useQueryParams } from '@/composables/useQueryParams';
import {
  addItemSeoSection,
  updateItemSeoSection,
  getSeoSectionItem,
  getHistoryChangesItemSeoCategory,
} from '@/services/apiTableAdmin.js';

import { isEqual } from 'lodash';

import { getFilterOption, getRegions } from '@/services/apiClient.js';
import { useCityStore } from '@/store/city.js';

import { useRoute, useRouter } from 'vue-router';

const route = useRoute();
const router = useRouter();

const citiesStore = useCityStore();

const title = ref('SEO разделов');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const isMenuOpen = ref(false);
const menuName = ref('');
const listСities = ref([]);
const seoItem = ref('');
const createItem = ref('');
const updateItem = ref('');
const inputUrl = ref('');
const historyChange = ref('');
const loading = ref(false);

const currentFormValues = computed(() => ({
  is_no_index: noIndex.value.value,
  sort: 200,
  h1: inputH1.value.value,
  title: inputTitle.value.value,
  description: inputDescr.value.value,
  city_id: selectedLocation.value,
  keywords: inputKeywords.value.value,
  seo_text: inputSeoText.value.value,
  header: inputHeader.value.value,
  footer: inputFooter.value.value,
  section_id: selectPartition.value.code,
  createItem: createItem.value,
  updateItem: updateItem.value,
}));

const isFormChanged = computed(() => {
  return !isEqual(initialValues.value, currentFormValues.value);
});
const id = route.params.id;

const selectedLocation = ref(null);
const locationOptions = ref([]);

const showExitConfirm = ref(false);
const sectionOption = ref(null);
const sectionId = ref('');

const selectPartition = ref({
  name: '',
  code: '',
});
const selectPartitions = ref(null);

const initialValues = ref(null);
// input
const city = ref({});
const cityId = ref(null);
const noIndex = ref({
  value: false,
  name: 'Noindex',
  error: false,
  success: false,
});
const inputH1 = ref({
  value: '',
  name: 'H1',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputTitle = ref({
  value: '',
  name: 'Title',

  validateType: 'empty',
  error: false,
  success: false,
});
const inputCity = ref({
  value: '',
  placeholder: 'города',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputDescr = ref({
  value: '',
  name: 'Description',

  validateType: 'empty',
  error: false,
  success: false,
});
const inputKeywords = ref({
  value: '',
  name: 'E-mail*',
  validateType: 'empty',

  error: false,
  success: false,
});
const inputSeoText = ref({
  value: '',
  name: 'Seo text*',
  validateType: 'empty',

  error: false,
  success: false,
});
const inputHeader = ref({
  value: '',
  name: 'Header',
  validateType: 'empty',

  error: false,
  success: false,
});
const inputFooter = ref({
  value: '',
  name: 'Footer',
  validateType: 'empty',
  error: false,
  success: false,
});
const { queryParams, loadQueryParamsFromRoute, updateQueryParams } =
  useQueryParams();

const getParametrQRL = async () => {
  await citiesStore.getСities();
  listСities.value = citiesStore.getSelectOption;

  if (id !== 'new') {
    historyChange.value = await getHistoryChangesItemSeoCategory(id);
    seoItem.value = await getSeoSectionItem(id);

    createItem.value = FORMATER('date', seoItem.value.data.created_at, '||');
    updateItem.value = FORMATER('date', seoItem.value.data.updated_at, '||');
    noIndex.value.value = seoItem.value.data?.is_no_index;
    inputH1.value.value = seoItem.value.data?.h1;
    inputTitle.value.value = seoItem.value.data?.title;
    cityId.value = seoItem.value.data?.city?.id;
    selectedLocation.value = seoItem.value.data?.city?.id;
    sectionId.value = seoItem.value.data?.section?.id;
    sectionOption.value = seoItem.value.data?.section;
    inputDescr.value.value = seoItem.value.data?.description;
    inputKeywords.value.value = seoItem.value.data?.keywords;
    inputSeoText.value.value = seoItem.value.data?.seo_text;
    inputHeader.value.value = seoItem.value.data?.header;
    inputFooter.value.value = seoItem.value.data?.footer;
    inputCity.value.value = seoItem.value?.data?.city?.title;
    city.value = seoItem?.value?.data?.city?.id;
    inputUrl.value = seoItem?.value?.data?.url?.url;
    initialValues.value = {
      is_no_index: seoItem.value.data.is_no_index,
      sort: seoItem.value.data.sort,
      h1: seoItem.value.data.h1,
      title: seoItem.value.data.title,
      description: seoItem.value.data.description,
      city_id: seoItem.value.data?.city?.id,
      keywords: seoItem.value.data.keywords,
      seo_text: seoItem.value.data.seo_text,
      header: seoItem.value.data.header,
      footer: seoItem.value.data.footer,
      section_id: seoItem.value.data?.section?.id.toString(),
      createItem: FORMATER('date', seoItem.value.data.created_at, '||'),
      updateItem: FORMATER('date', seoItem.value.data.updated_at, '||'),
    };
    if (seoItem?.value?.data?.section?.id) {
      selectPartition.value = selectPartitions.value.find(
        (el) => el.code == seoItem.value?.data?.section?.id
      );
    }
  } else {
    initialValues.value = {
      is_no_index: false,
      sort: 200,
      h1: '',
      title: '',
      description: '',
      city_id: null,
      keywords: '',
      seo_text: '',
      header: '',
      footer: '',
      section_id: '',
      createItem: createItem.value,
      updateItem: updateItem.value,
    };
  }
};
const getSection = async () => {
  loadQueryParamsFromRoute();

  const data = await getFilterOption();

  selectPartitions.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
};
const getlocation = async () => {
  const response = await getRegions();

  locationOptions.value = response;
};
const resetFilterValue = () => {
  noIndex.value.value = initialValues.value.is_no_index;
  inputH1.value.value = initialValues.value.h1;
  inputTitle.value.value = initialValues.value.title;
  inputDescr.value.value = initialValues.value.description;
  cityId.value = initialValues.value.city_id;
  inputKeywords.value.value = initialValues.value.keywords;
  inputSeoText.value.value = initialValues.value.seo_text;
  inputHeader.value.value = initialValues.value.header;
  inputFooter.value.value = initialValues.value.footer;
  sectionId.value = initialValues.value.section_id;
  createItem.value = initialValues.value.createItem;
  updateItem.value = initialValues.value.updateItem;

  queryParams.value.is_no_index = '';
  queryParams.value.sort = '';
  queryParams.value.h1 = '';
  queryParams.value.title = '';
  queryParams.value.description = '';
  queryParams.value.city_id = '';
  queryParams.value.keywords = '';
  queryParams.value.seo_text = '';
  queryParams.value.header = '';
  queryParams.value.footer = '';
  queryParams.value.section_id = '';
  updateQueryParams();
};
const saveForm = async () => {
  const isValidateStatus = useValidate([
    inputH1.value,
    inputTitle.value,
    inputDescr.value,
    inputKeywords.value,
    inputSeoText.value,
    inputHeader.value,
    inputFooter.value,
  ]);
  if (!isValidateStatus) return;

  const formData = new FormData();

  formData.append('is_no_index', FORMATER('togller', noIndex.value.value));
  formData.append('sort', 200);
  formData.append('h1', inputH1.value.value);
  formData.append('title', inputTitle.value.value);
  formData.append('description', inputDescr.value.value);
  formData.append('section_id', selectPartition.value.code);
  formData.append('keywords', inputKeywords.value.value);
  formData.append('seo_text', inputSeoText.value.value);
  formData.append('header', inputHeader.value.value);
  formData.append('footer', inputFooter.value.value);
  if (selectedLocation.value) {
    formData.append('city_id', selectedLocation.value);
  } else formData.append('is_no_indicate_city', 1);

  loading.value = true;
  if (id === 'new') {
    const res = addItemSeoSection(formData);
    if (res) {
      loading.value = false;
    }
    if (res.success !== false) {
      router.back();
    }
  } else {
    const res = updateItemSeoSection(id, formData);
    if (res) {
      loading.value = false;
    }
    if (res.success !== false) {
      router.back();
    }
  }
};
const openMenu = (name) => {
  menuName.value = name;
  isMenuOpen.value = true;
};
const chouseItem = (item) => {
  createItem.value = FORMATER('date', item.data.created_at, '||');
  updateItem.value = FORMATER('date', item.data.updated_at, '||');
  noIndex.value.value = item.data?.is_no_index;
  inputH1.value.value = item.data?.h1;
  inputTitle.value.value = item.data?.title;
  cityId.value = item.data?.city?.id;
  selectedLocation.value = item.data?.city?.id;
  sectionId.value = item.data?.section?.id;
  sectionOption.value = item.data?.section;
  inputDescr.value.value = item.data?.description;
  inputKeywords.value.value = item.data?.keywords;
  inputSeoText.value.value = item.data?.seo_text;
  inputHeader.value.value = item.data?.header;
  inputFooter.value.value = item.data?.footer;
  inputCity.value.value = item.data?.city?.title;
  city.value = item?.data?.city?.id;
  inputUrl.value = item?.data?.url?.url;
  isMenuOpen.value = false;
};

const rejectPublication = () => {
  if (isFormChanged.value) {
    showExitConfirm.value = true;
  } else {
    router.back();
  }
};

const confirmExit = () => {
  showExitConfirm.value = false;
  router.back();
};

const cancelExit = () => {
  showExitConfirm.value = false;
};
onMounted(() => {
  getParametrQRL();
  getSection();
  getlocation();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 16px 24px 16px 24px;
  display: flex;
  flex-direction: column;
  width: calc(100% - 50px);
  &__header {
    margin-bottom: 20px;
  }
  @media (max-width: 1024px) {
    height: calc(100vh - 60px);
    margin-top: 85px;
  }

  &__main {
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    // margin: 16px 12px 16px 0px;
    padding: 12px 24px;
    flex-direction: column;
    min-height: calc(100vh - 120px);
    &-manu {
      display: flex;
      justify-content: space-between;
    }
  }
  &__manu-item {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  &__manu-title {
    font-size: 16px;
    font-weight: 700;
    color: #003bce;
  }

  &-option {
    display: flex;
    flex-direction: column;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 12px 24px;
    &__list-item {
      padding: 12px 0;
      border-top: 1px solid #d6d6d6;
    }
    &__btn-box {
      padding: 12px 0;
      border-top: 1px solid #d6d6d6;
    }
    @media (max-width: 1024px) {
      margin: 16px 0;
    }

    &__btn-box {
      display: flex;
      gap: 16px;
      align-items: center;
    }
    &__title-box {
      display: flex;
      justify-content: space-between;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      width: 100%;
      &-btn {
        display: flex;
        align-self: center;
        span {
          align-self: center;
        }
      }
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__more {
      display: flex;
      align-items: center;
      justify-content: space-between;
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        color: #3366ff;
      }
    }
  }
  &-form {
    max-width: 600px;
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    border-radius: 4px;
    margin: 16px 12px 16px 0px;
  }
}

.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-window {
  background: #fff;
  padding: 32px;
  border-radius: 6px;
  width: 380px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: #3366ff;
  padding-bottom: 24px;
  border-bottom: 1px solid #d6d6d6;
  margin-bottom: 16px;
}

.modal-actions {
  display: flex;
  gap: 16px;
}
</style>
